package app.awavenue.c001apk.data

import kotlin.random.Random

/** The randomised device profile sent with every API request, as generated by the Flutter app. */
data class DeviceParams(
    val versionName: String,
    val apiVersion: String,
    val versionCode: String,
    val manufacturer: String,
    val brand: String,
    val model: String,
    val buildNumber: String,
    val sdkInt: String,
    val androidVersion: String,
    val xAppDevice: String,
) {
    val userAgent: String
        get() = "Dalvik/2.1.0 (Linux; U; Android $androidVersion; $model $buildNumber) " +
            "(#Build; $brand; $model; $buildNumber; $androidVersion) " +
            "+CoolMarket/$versionName-$versionCode-${Protocol.MODE}"

    /** Rebuilds `X-App-Device`, which encodes this profile's device, manufacturer and model. */
    fun reissueXAppDevice(szlmId: String, random: Random = Random.Default): DeviceParams =
        copy(xAppDevice = deviceToken(szlmId, manufacturer, brand, model, buildNumber, random))

    companion object {
        private val manufacturers = listOf(
            "Samsung", "Google", "Huawei", "Xiaomi", "OnePlus", "Sony", "LG", "Motorola", "HTC",
            "Nokia", "Lenovo", "Asus", "ZTE", "Alcatel", "OPPO", "Vivo", "Realme",
        )
        private val brands = listOf(
            "Samsung", "Google", "Huawei", "Xiaomi", "Redmi", "OnePlus", "Sony", "LG", "Motorola",
            "HTC", "Nokia", "Lenovo", "Asus", "ZTE", "Alcatel", "OPPO", "Vivo", "Realme",
        )
        private val androidVersions = listOf(
            "5.0.1", "6.0", "7.0", "7.1.1", "8.0.0", "8.1.0", "9", "10", "11", "12", "13", "14",
        )

        fun generate(szlmId: String = "", random: Random = Random.Default): DeviceParams {
            val manufacturer = manufacturers.random(random)
            val brand = brands.random(random)
            val model = randHex(6, random)
            val buildNumber = randHex(32, random)
            return DeviceParams(
                versionName = Protocol.VERSION_NAME,
                apiVersion = Protocol.API_VERSION,
                versionCode = Protocol.VERSION_CODE,
                manufacturer = manufacturer,
                brand = brand,
                model = model,
                buildNumber = buildNumber,
                sdkInt = (random.nextInt(14) + 21).toString(),
                androidVersion = androidVersions.random(random),
                xAppDevice = deviceToken(szlmId, manufacturer, brand, model, buildNumber, random),
            )
        }

        private fun deviceToken(
            szlmId: String,
            manufacturer: String,
            brand: String,
            model: String,
            buildNumber: String,
            random: Random,
        ): String = TokenUtils.encodeDevice(
            "${szlmId.ifEmpty { randHex(32, random) }}; ; ; ${randomMacAddress(random)}; " +
                "$manufacturer; $brand; $model; $buildNumber; null",
        )

        private fun randHex(length: Int, random: Random): String =
            buildString { repeat(length) { append("0123456789ABCDEF"[random.nextInt(16)]) } }

        private fun randomMacAddress(random: Random): String {
            val bytes = random.nextBytes(6)
            bytes[0] = ((bytes[0].toInt() and 0xFE) or 0x02).toByte()
            return bytes.joinToString(":") { "%02X".format(it) }
        }
    }
}
